import{z as n,x as s,o as A,c as p,q as t,j as r,D as a,d as e,s as o,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"持续学习的评测协议","description":"","frontmatter":{"title":"持续学习的评测协议","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-eval-protocol.md","filePath":"llm/continual-eval-protocol.md","lastUpdated":1791063341000}'),d={name:"llm/continual-eval-protocol.md"};function m(h,E,c,C,D,u){const l=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=t('<h1 id="持续学习的评测协议" tabindex="-1">持续学习的评测协议 <a class="header-anchor" href="#持续学习的评测协议" aria-label="Permalink to &quot;持续学习的评测协议&quot;">​</a></h1><div class="epigraph"><p>持续学习的学生不能只考期末：这门课的记分单位是整条成绩轨迹，不是最后一个点。</p><footer>—— 据 López-Paz 与 Ranzato 2017、Chaudhry 等 2019 整理</footer></div><p><a href="/llm/continual-feedback-privacy">上一课</a>把住入口，本课管出口：每次更新到底好不好、这门持续学习的课整体学得怎么样，需要一个可比、可复核、防作弊的记分协议。第一单元已把遗忘写成<a href="/llm/forgetting-metrics">度量</a>，那是单条序列的读数；本课把它扩成生产环的常设制度：探针怎么冻结、门怎么设、轨迹怎么记账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单点评测在持续学习里有系统性盲区。只评新任务，看不见旧能力正在漏；只评旧任务，新任务可能根本没学会；只看线上均值，局部灾难被全局平均稀释。更隐蔽的是评测集自身的漂移：静态题库会被环里的模型与训练数据慢慢背下来，成绩虚涨；动态题库又引入新题方差。持续学习比批处理更怕这个，因为它的训练数据就是线上的流量——评测集与训练集天然挨得近，不设防的协议会安静地变成自我打分。</p><h3 id="轨迹指标" tabindex="-1">轨迹指标 <a class="header-anchor" href="#轨迹指标" aria-label="Permalink to &quot;轨迹指标&quot;">​</a></h3><p>把第 \\(t\\) 次更新后任务 \\(i\\) 的探针成绩记为 \\(R_{t,i}\\)，三个数概括一条轨迹。平均成绩 \\(\\bar R=\\frac{1}{T}\\sum_i R_{T,i}\\)，期末总分。后向迁移 \\(B=\\frac{1}{T-1}\\sum_i (R_{T,i}-R_{i,i})\\)，负值就是「后来的学习对已有能力的税」。新任务起点成绩与单独学该任务的基线的差衡量前向迁移，反映可塑性。三个数一起看才构成稳定-可塑性的完整读数：只优化 \\(\\bar R\\) 会压抑一切更新，只盯新任务会交重遗忘税。</p><p><span class="marginnote">用数字看「后向迁移税」：设训完客服任务时成绩 80 分，三个任务全学完后客服只剩 65 分，则客服那项 \\(R_{T,i}-R_{i,i}=-15\\)。若几个旧任务都在 -15 上下，平均后向迁移 \\(B\\approx-15\\)——这个负数就是后续学习对旧能力收的税，越接近零越好。</span></p><p><span class="marginnote">GEM 论文（López-Paz 与 Ranzato 2017）定型了后向/前向迁移的记法；Chaudhry 等 2019 把小样本回放下的同一套指标做成标准基准口径。生产里直接沿用记法即可，别再造第二套术语。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>制度四件套。<strong>冻结探针电池</strong>：每个能力域一组固定题，版本化、封存、永不参与任何训练，入库走与<a href="/llm/eval-contamination">评测去污染流水线</a>相同的 n-gram 与嵌入查重；电池本身过时了就换版，新旧版并跑一个周期对齐读数。<strong>发布门</strong>：新任务达标线＋旧域回归带宽（比如任一旧域探针降幅超 \\(\\delta\\) 即拦下），带宽按域的历史方差定，不拍脑袋。<strong>滚动外部题</strong>：接<a href="/llm/live-benchmarks">动态基准与题库轮换</a>的口径看慢变量，防止内部电池全体虚涨。<strong>轨迹台账</strong>：每次更新的 \\(R_{t,i}\\) 全量入账，带数据配方、模型版本、探针版本——没有台账的协议只有当次读数，没法回答「从哪次更新开始坏的」。</p>',11)),(A(),r(i,null,{default:a(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E7%AC%AC%20t%20%E6%AC%A1%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20PROBE%5B%22%E5%86%BB%E7%BB%93%E6%8E%A2%E9%92%88%E7%94%B5%E6%B1%A0%E5%85%A8%E9%87%8F%E5%9B%9E%E5%BD%92%22%5D%0A%20%20UPD%20--%3E%20ROLL%5B%22%E6%BB%9A%E5%8A%A8%E5%A4%96%E9%83%A8%E9%A2%98%20%2B%20%E7%BA%BF%E4%B8%8A%E7%81%B0%E5%BA%A6%E8%83%9C%E7%8E%87%22%5D%0A%20%20PROBE%20--%3E%20GATE%7B%22%E6%96%B0%E4%BB%BB%E5%8A%A1%E8%BE%BE%E6%A0%87%E4%B8%94%E6%97%A7%E5%9F%9F%E9%99%8D%E5%B9%85%E2%89%A4%CE%B4%3F%22%7D%0A%20%20ROLL%20--%3E%20GATE%0A%20%20GATE%20--%3E%7C%E5%90%A6%7C%20BLOCK%5B%22%E6%8B%A6%E4%B8%8B%EF%BC%9A%E5%9B%9E%E6%BB%9A%E6%88%96%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20GATE%20--%3E%7C%E6%98%AF%7C%20LEDGER%5B%22%E8%AE%B0%E5%85%A5%E8%BD%A8%E8%BF%B9%E5%8F%B0%E8%B4%A6%20R_t%2Ci%22%5D%0A%20%20LEDGER%20--%3E%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E6%AC%A1%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"门为什么要带宽而不是单点比较：探针读数有采样与训练方差，把噪声当回归会冻死整个环，把回归当噪声会放行真事故。正确做法是先量出「无更新也这么抖」的基线方差——固定模型重跑探针的方差、种子与解码温度的贡献——带宽取方差的倍数。这在统计上就是把「检出回归的功效」当作协议参数来设计，而不是事后解释。线上侧同理：灰度胜率的样本量按最小可检测效应反推，样本不够的判定是在抛硬币。",-1)),(A(),r(i,null,{default:a(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%9B%BA%E5%AE%9A%E6%A8%A1%E5%9E%8B%E9%87%8D%E8%B7%91%E6%8E%A2%E9%92%88%20N%20%E6%AC%A1%22%5D%20--%3E%20V%5B%22%E9%87%8F%E5%87%BA%E5%9F%BA%E7%BA%BF%E6%96%B9%E5%B7%AE%3A%E7%A7%8D%E5%AD%90%2F%E8%A7%A3%E7%A0%81%E6%B8%A9%E5%BA%A6%2F%E9%87%87%E6%A0%B7%22%5D%0A%20%20V%20--%3E%20B%5B%22%E5%B8%A6%E5%AE%BD%20%CE%B4%20%3D%20%E5%9F%BA%E7%BA%BF%E6%96%B9%E5%B7%AE%E7%9A%84%20k%20%E5%80%8D%22%5D%0A%20%20B%20--%3E%20G%7B%22%E6%97%A7%E5%9F%9F%E9%99%8D%E5%B9%85%20%E2%89%A4%20%CE%B4%3F%22%7D%0A%20%20G%20--%3E%7C%22%E6%98%AF%3A%E5%9C%A8%E5%99%AA%E5%A3%B0%E5%B8%A6%E5%86%85%22%7C%20PASS%5B%22%E6%94%BE%E8%A1%8C%3A%E6%9C%AA%E6%A3%80%E5%87%BA%E5%9B%9E%E5%BD%92%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%A6%3A%E8%B6%85%E5%87%BA%E5%99%AA%E5%A3%B0%E5%B8%A6%22%7C%20FAIL%5B%22%E6%8B%A6%E6%88%AA%3A%E7%96%91%E4%BC%BC%E7%9C%9F%E5%9B%9E%E5%BD%92%22%5D%0A%20%20S%5B%22%E7%81%B0%E5%BA%A6%E8%83%9C%E7%8E%87%E6%A0%B7%E6%9C%AC%E9%87%8F%22%5D%20-.-%3E%7C%22%E6%8C%89%E6%9C%80%E5%B0%8F%E5%8F%AF%E6%A3%80%E6%B5%8B%E6%95%88%E5%BA%94%E5%8F%8D%E6%8E%A8%22%7C%20G%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">「基线方差」就是「什么都不改时读数自己会抖多少」：同一个模型把探针重跑十遍，成绩也会因随机种子、解码温度不同而上下浮动。先量出这个天然抖动范围，再放大几倍当门带宽——低于它的下降多半是噪声，超过它的才值得报警。</span></p><p><a href="/llm/human-eval-protocol">人类评测协议</a>与<a href="/llm/pairwise-label-protocol">成对比较协议</a>在环里的位置是仲裁与抽检：探针答不了的开放维度（语气、有用性）靠人评，人评贵所以只抽样；标注一致性要持续监控，标注员疲劳是轨迹里一种特殊的「漂移」——变的不是模型而是尺子。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>协议的失效方式要有预案。探针泄漏：环里任何组件把探针题喂进训练，读数从此虚高，抽查式插入金丝雀题可发现。探针陈化：能力域变了而电池没变，门会拦住本该放行的更新——并跑换版是唯一解。带宽过宽：等于没有门，宁可在历史事故上校准。外部基准饱和（见<a href="/llm/benchmark-saturation">基准饱和</a>）让滚动题也递减信息量。最后，协议覆盖不了「该不该学」的判断：探针只能回答「这次更新有没有变好」，方向对不对是上一单元漂移检测与产品判断的事——把评测协议当决策引擎，是持续学习组织最体面的偷懒。</p><p><span class="marginnote">初学者容易把评测协议当成「考完就算」的一次性动作。持续学习里它是常设制度：探针题会被环内模型慢慢背熟，读数变成自我打分，所以电池要防污染、要定期换版并跑对齐；没有轨迹台账，出了问题连「从哪次更新开始坏的」都答不出来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>记分单位是轨迹：平均成绩、后向迁移、前向迁移三个数合读，缺一个都会骗人。</li><li>探针电池必须冻结、版本化、防污染，换版并跑对齐读数。</li><li>发布门是「新任务达标＋旧域带宽」，带宽由基线方差校准，不是拍脑袋的常数。</li><li>外部滚动题防自我打分，人评做仲裁与抽检，标注一致性本身也要监控。</li><li>轨迹台账是协议的存根：无台账则无法归因「从哪次更新开始坏的」。</li><li>出处：López-Paz 与 Ranzato 2017（GEM 指标）；Chaudhry 等 2019（回放基准口径）；Hardt 等 2016（方差与稳定性的统计口径）。</li></ul>',7))])}const F=n(d,[["render",m]]);export{f as __pageData,F as default};
